
  CREATE TABLE "COURIERS"
   (	"ID" NUMBER(19,0) GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE	NOT NULL ENABLE,
	"DEPOT_CODE" VARCHAR2(10),
	"FULL_NAME" VARCHAR2(100) NOT NULL ENABLE,
	"PHONE" VARCHAR2(32),
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE,
	 FOREIGN KEY ("DEPOT_CODE")
	  REFERENCES "DEPOTS" ("CODE") ENABLE
   ) ;


  CREATE TABLE "DELIVERIES"
   (	"ID" NUMBER(10,0) GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE	NOT NULL ENABLE,
	"PARCEL_ID" NUMBER(19,0) NOT NULL ENABLE,
	"COURIER_ID" NUMBER(19,0),
	"ATTEMPTED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	"OUTCOME" VARCHAR2(20),
	"DELIVERED_TO" VARCHAR2(100),
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE,
	 FOREIGN KEY ("COURIER_ID")
	  REFERENCES "COURIERS" ("ID") ENABLE,
	 CONSTRAINT "DELIVERIES_PARCEL_FK" FOREIGN KEY ("PARCEL_ID")
	  REFERENCES "PARCELS" ("ID") ENABLE
   ) ;


  CREATE TABLE "DEPOTS"
   (	"CODE" VARCHAR2(10),
	"NAME" VARCHAR2(100) NOT NULL ENABLE,
	"CITY" VARCHAR2(100),
	 PRIMARY KEY ("CODE")
  USING INDEX  ENABLE
   ) ;


  CREATE TABLE "PARCELS"
   (	"ID" NUMBER(19,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TRACKING_NUMBER" VARCHAR2(20) NOT NULL ENABLE,
	"DEPOT_CODE" VARCHAR2(10),
	"WEIGHT_GRAMS" NUMBER(10,0) NOT NULL ENABLE,
	"WEIGHT_KG" NUMBER GENERATED ALWAYS AS ("WEIGHT_GRAMS"/1000) VIRTUAL ,
	"STATUS" VARCHAR2(20) DEFAULT NULL NOT NULL ENABLE,
	"ORDER" VARCHAR2(32),
	"LABEL_NOTE" VARCHAR2(100) DEFAULT 'fragile -- handle with care; don''t stack',
	"SENDER" VARCHAR2(100),
	 CONSTRAINT "PARCELS_PK" PRIMARY KEY ("ID")
  USING INDEX  ENABLE,
	 UNIQUE ("TRACKING_NUMBER")
  USING INDEX  ENABLE,
	 CONSTRAINT "PARCELS_DEPOT_FK" FOREIGN KEY ("DEPOT_CODE")
	  REFERENCES "DEPOTS" ("CODE") ENABLE
   ) ;

